use xiom.io;

use xiom.string;
fn main() -> Int {
  let groceries: Vec[Str] = Vec[Str].new();
  groceries.push("apples");
  groceries.push("bananas");
  groceries.push("carrots");

  io.println("Grocery List:");
  let i: Int = 0;
  while i < groceries.len() {
    match groceries.get(i) {
      Some(item) -> io.println(string.int_to_str(i + 1) + ". " + item);
      None -> {}
    }
    i = i + 1;
  }

  io.println("Total items: " + string.int_to_str(groceries.len()));
  return 0;
}
